window.docContents[106].resolve({"/Basics/#Logical-Foundations--Basics___-Functional-Programming-in-Lean--Proof-by-Case-Analysis--Binary-Numerals":{"contents":"We can generalize our unary representation of natural numbers to\nthe more efficient binary representation by treating a binary\nnumber as a sequence of constructors b0 and b1 (representing 0s\nand 1s), terminated by a z.For example:decimal                binary   unary\n      0                     z   zero\n      1                  b1 z   succ zero\n      2             b0 (b1 z)   succ (succ zero)\n      3             b1 (b1 z)   succ (succ (succ zero))\n      4        b0 (b0 (b1 z))   succ (succ (succ (succ zero)))\n      5        b1 (b0 (b1 z))   succ (succ (succ (succ (succ zero))))\n      6        b0 (b1 (b1 z))   succ (succ (succ (succ (succ (succ zero)))))\n      7        b1 (b1 (b1 z))   succ (succ (succ (succ (succ (succ (succ zero))))))\n      8   b0 (b0 (b0 (b1 z)))   succ (succ (succ (succ (succ (succ (succ (succ zero)))))))\nNote that the low-order bit is on the left and the high-order bit\nis on the right — the opposite of the way binary numbers are\nusually written.  This choice makes them easier to manipulate.(Comprehension check: What unary numeral does b0 z represent?)inductive Bin : Type where\n  | z\n  | b0 (n : Bin)\n  | b1 (n : Bin)\n\nattribute [pp_nodot] Bin.b1 Bin.b0\n\ndef incr (m : Bin) : Bin\n  := solution!(match m with\n  | .z => .b1 .z\n  | .b0 m' => .b1 m'\n  | .b1 m' => .b0 (incr m'))\n\ndef binToNat (m : Bin) : Nat\n  := solution!(match m with\n  | .z => zero\n  | .b0 m' => binToNat m' * two\n  | .b1 m' => binToNat m' * two + one)\n\ntheorem incr_test1 : incr (.b1 .z) = .b0 (.b1 .z) := solution!(by rfl)\ntheorem incr_test2 : incr (.b0 (.b1 .z)) = .b1 (.b1 .z) := solution!(by rfl)\ntheorem incr_test3 : incr (.b1 (.b1 .z)) = .b0 (.b0 (.b1 .z)) := solution!(by rfl)\n\ntheorem incr_z : incr .z = .b1 .z := solution!(by rfl)\ntheorem incr_b0 (m : Bin) : incr (.b0 m) = .b1 m := solution!(by rfl)\ntheorem incr_b1 (m : Bin) : incr (.b1 m) = .b0 (incr m) := solution!(by rfl)\n\ntheorem binToNat_z : binToNat .z = zero := solution!(by rfl)\ntheorem binToNat_b0 (m : Bin) : binToNat (.b0 m) = binToNat m * two := solution!(by rfl)\ntheorem binToNat_b1 (m : Bin) : binToNat (.b1 m) = binToNat m * two + one := solution!(by rfl)\ninductive Bin : Type where\n  | z\n  | b0 (n : Bin)\n  | b1 (n : Bin)\n\nattribute [pp_nodot] Bin.b1 Bin.b0\n\ndef incr (m : Bin) : Bin\n  := sorry\n\ndef binToNat (m : Bin) : Nat\n  := sorry\n\ntheorem incr_test1 : incr (.b1 .z) = .b0 (.b1 .z) := sorry\ntheorem incr_test2 : incr (.b0 (.b1 .z)) = .b1 (.b1 .z) := sorry\ntheorem incr_test3 : incr (.b1 (.b1 .z)) = .b0 (.b0 (.b1 .z)) := sorry\n\ntheorem incr_z : incr .z = .b1 .z := sorry\ntheorem incr_b0 (m : Bin) : incr (.b0 m) = .b1 m := sorry\ntheorem incr_b1 (m : Bin) : incr (.b1 m) = .b0 (incr m) := sorry\n\ntheorem binToNat_z : binToNat .z = zero := sorry\ntheorem binToNat_b0 (m : Bin) : binToNat (.b0 m) = binToNat m * two := sorry\ntheorem binToNat_b1 (m : Bin) : binToNat (.b1 m) = binToNat m * two + one := sorry\ninductive Bin : Type where\n  | z\n  | b0 (n : Bin)\n  | b1 (n : Bin)\n\nattribute [pp_nodot] Bin.b1 Bin.b0\n\ndef incr (m : Bin) : Bin\n  := sorry\n\ndef binToNat (m : Bin) : Nat\n  := sorry\n\ntheorem incr_test1 : incr (.b1 .z) = .b0 (.b1 .z) := sorry\ntheorem incr_test2 : incr (.b0 (.b1 .z)) = .b1 (.b1 .z) := sorry\ntheorem incr_test3 : incr (.b1 (.b1 .z)) = .b0 (.b0 (.b1 .z)) := sorry\n\ntheorem incr_z : incr .z = .b1 .z := sorry\ntheorem incr_b0 (m : Bin) : incr (.b0 m) = .b1 m := sorry\ntheorem incr_b1 (m : Bin) : incr (.b1 m) = .b0 (incr m) := sorry\n\ntheorem binToNat_z : binToNat .z = zero := sorry\ntheorem binToNat_b0 (m : Bin) : binToNat (.b0 m) = binToNat m * two := sorry\ntheorem binToNat_b1 (m : Bin) : binToNat (.b1 m) = binToNat m * two + one := sorry\nYou may find your previous proofs of zero_add_one, one_add_one, zero_mul_two,\none_mul_two, and two_mul_two useful here.example : binToNat (.b0 (.b1 .z)) = two := solution!(by\n  rewrite [binToNat_b0, binToNat_b1, binToNat_z]\n  rewrite [zero_mul_two, zero_add_one, one_mul_two]\n  rfl\n)\ntheorem binToNat_test1 : binToNat (incr (.b1 .z)) = add one (binToNat (.b1 .z)) := solution!(by\n    rewrite [binToNat_b1, binToNat_z, incr_b1, binToNat_b0, incr_z, binToNat_b1, binToNat_z]\n    rewrite [zero_mul_two, zero_add_one, one_mul_two, one_add_one]\n    rfl\n)\ntheorem binToNat_test2 : binToNat (incr (incr (.b1 .z))) = add two (binToNat (.b1 .z)) := solution!(by\n  rewrite [binToNat_b1, binToNat_z, incr_b1, incr_b0, binToNat_b1, incr_z, binToNat_b1, binToNat_z]\n  rewrite [zero_mul_two, zero_add_one, one_mul_two]\n  rfl\n)\ntheorem binToNat_test3 : binToNat (.b0 (.b0 (.b1 .z))) = four := solution!(by\n  rewrite [binToNat_b0, binToNat_b0, binToNat_b1, binToNat_z]\n  rewrite [zero_mul_two, zero_add_one, one_mul_two, two_mul_two]\n  rfl\n)\n\nattribute [irreducible] incr binToNat\nexample : binToNat (.b0 (.b1 .z)) = two := sorry\ntheorem binToNat_test1 : binToNat (incr (.b1 .z)) = add one (binToNat (.b1 .z)) := sorry\ntheorem binToNat_test2 : binToNat (incr (incr (.b1 .z))) = add two (binToNat (.b1 .z)) := sorry\ntheorem binToNat_test3 : binToNat (.b0 (.b0 (.b1 .z))) = four := sorry\n\nattribute [irreducible] incr binToNat\nexample : binToNat (.b0 (.b1 .z)) = two := sorry\ntheorem binToNat_test1 : binToNat (incr (.b1 .z)) = add one (binToNat (.b1 .z)) := sorry\ntheorem binToNat_test2 : binToNat (incr (incr (.b1 .z))) = add two (binToNat (.b1 .z)) := sorry\ntheorem binToNat_test3 : binToNat (.b0 (.b0 (.b1 .z))) = four := sorry\n\nattribute [irreducible] incr binToNat\n\n\nend Nat\nend Nat\nend Nat\n\n\n","context":"Logical Foundations\u0009Basics: Functional Programming in Lean\u0009Proof by Case Analysis","header":"2.4.4. Binary Numerals","id":"/Basics/#Logical-Foundations--Basics___-Functional-Programming-in-Lean--Proof-by-Case-Analysis--Binary-Numerals"}});